INSERT INTO `progmess` VALUES (1,'------Beta version------\r\nBienvenue dans la beta-version de NetTrader.\r\n\r\nMerci d\'indiquer le mauvais fonctionnement du logiciel dans le forum de NetTrader 2.\r\n\r\nBon jeu ;)','http://www.nettrader.fr',''),(2,'Bonjour\r\n\r\nBienvenu dans la version logiciel du jeu NetTrader 2. N\'hésitez pas à fournir vos avis via le forum.\r\n\r\nBon trades','http://www.nettrader.fr','');
