--
-- Table structure for table `reqlist`
--

DROP TABLE IF EXISTS `reqlist`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reqlist` (
  `idreq` smallint(6) NOT NULL AUTO_INCREMENT,
  `libelreq` varchar(255) NOT NULL DEFAULT '',
  `req` text NOT NULL,
  `nbutil` smallint(6) NOT NULL DEFAULT '0',
  PRIMARY KEY (`idreq`)
) ENGINE=MyISAM AUTO_INCREMENT=36 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `reqlist`
--

LOCK TABLES `reqlist` WRITE;
/*!40000 ALTER TABLE `reqlist` DISABLE KEYS */;
INSERT INTO `reqlist` VALUES (4,'Joueurs en ligne','SELECT compte.pseudonyme AS Pseudo, FROM_UNIXTIME( MAX(tempsconnect) )  AS  \'Heure de connexion\'\r\nFROM compte,Session\r\nWHERE compte.idcompte = Session.idcompte AND tempsconnect>UNIX_TIMESTAMP() - 30 * 60\r\nGROUP BY pseudonyme\r\nORDER BY tempsconnect DESC',213),(5,'Verification Actions historique->Portefeuille','SELECT portef.idcompte as id1,historique.idcompte as id2, compte.pseudonyme , cacval.nom, SUM( historique.nbr * SIGN( historique.taxe )  )  AS restant, COALESCE( portef.quant, 0  )  - SUM( historique.nbr * SIGN( historique.taxe )  )  AS nbrerreur, COALESCE( portef.quant, 0  )  AS Possede\r\nFROM historique\r\nLEFT  JOIN portef\r\nUSING ( idcompte, codesico ) \r\nLEFT  JOIN cacval\r\nON historique.codesico = cacval.codesico \r\nLEFT JOIN compte\r\nON compte.idcompte = historique.idcompte\r\nGROUP  BY compte.pseudonyme , cacval.nom\r\nHAVING nbrerreur <> 0\r\nORDER  BY compte.pseudonyme ASC',73),(6,'30 premieres Actions (test flux)','SELECT nom, valeur, FROM_UNIXTIME( lasttime ) AS \'Date Action\', FROM_UNIXTIME( lasttimedown ) AS \'Date Téléchargement\' , authachat,down\r\nFROM `cacval` \r\nWHERE 1 ORDER BY lasttime ASC',165),(7,'Nombre d\'ordre executé','SELECT compte.pseudonyme, FROM_UNIXTIME(compte.dateactivite) as dateact,COUNT( idhisto )  AS Nbordres\r\nFROM compte, historique\r\nWHERE compte.idcompte = historique.idcompte\r\nGROUP  BY pseudonyme,dateact\r\nORDER  BY Nbordres DESC',30),(8,'Verification cashback','SELECT historique.idcompte, compte.pseudonyme, 10000 + SUM( ( valeurunique * nbr + taxe ) * SIGN( -historique.taxe )  )  AS restant, round(10000 + SUM( ( valeurunique * nbr + taxe ) * SIGN( -historique.taxe )  )  - compte.cashback,2) AS nbrerreur, compte.cashback AS Possede\r\nFROM compte,historique,cacval\r\nwhere compte.idcompte = historique.idcompte\r\nAND historique.codesico = cacval.codesico\r\nGROUP  BY idcompte, compte.pseudonyme\r\nHAVING nbrerreur <>0\r\nORDER  BY historique.idcompte ASC ',36),(9,'Action le plus possédé','SELECT cacval.nom as Nom,SUM(portef.quant) as \'Quantitée\', SUM(portef.quant * cacval.valeur)  AS Valeur FROM cacval,portef WHERE cacval.codesico = portef.codesico GROUP BY cacval.nom ORDER BY Valeur DESC',33),(10,'Nouveau inscrit au dernieres 24h','SELECT pseudonyme,FROM_UNIXTIME(dateinscr) AS \"Date d\'inscription\" FROM compte where dateinscr>UNIX_TIMESTAMP()-24*3600',385),(11,'Actions achetés et vendu depuis 2h','SELECT cacval.nom as Nom,historique.sens  as Sens,SUM(historique.nbr) as \'Quantitée\', SUM(historique.nbr * cacval.valeur)  AS \"Valeur ( € ) \" FROM cacval,historique WHERE cacval.codesico = historique.codesico \r\nAND historique.temps>UNIX_TIMESTAMP()-2*3600\r\nGROUP BY cacval.nom,historique.sens ORDER BY \"Valeur ( € ) \" DESC',76),(12,'Dernière connexion des joueurs','SELECT FROM_UNIXTIME( dateactivite, \'%d %M %Y\' ) AS \"Dernière connexion\", count( * ) as \"Nombre\"\r\nFROM `compte`\r\nWHERE dateactivite >0\r\nGROUP BY \"Dernière connexion\"\r\nORDER BY dateactivite DESC',390),(13,'Dernière connect','SELECT FROM_UNIXTIME( dateactivite ) as Date\r\nFROM `compte`\r\nWHERE pseudonyme = \'Sethan\'',19),(14,'Gain de lignes à la maintenance','SELECT COUNT( * ) AS \'Nombre de lignes à gagner\'\r\nFROM compte, historique\r\nWHERE compte.idcompte = historique.idcompte\r\nAND dateactivite < UNIX_TIMESTAMP( ) -3600 *24 *30 *2\r\nAND (\r\ndateactivite >0\r\nOR (\r\ndateactivite =0\r\nAND dateinscr < UNIX_TIMESTAMP( ) -3600 *24 *30\r\n)\r\n)',26),(15,'Gain de ligne d\'histo par joueur','SELECT compte.idcompte AS id, compte.pseudonyme AS pseudo, dateactivite AS seclast,\r\nIF (\r\ndateactivite >0, FROM_UNIXTIME( dateactivite ) , \'\'\r\n) AS lastconnect, FROM_UNIXTIME( dateinscr ) AS \'date d\\\\\'inscription\', COUNT( * ) as \'Lignes d\\\\\'historique\'\r\nFROM compte, historique\r\nWHERE compte.idcompte = historique.idcompte\r\nAND dateactivite < UNIX_TIMESTAMP( ) -3600 *24 *30 *2\r\nAND (\r\ndateactivite >0\r\nOR (\r\ndateactivite =0\r\nAND dateinscr < UNIX_TIMESTAMP( ) -3600 *24 *30\r\n)\r\n)\r\nGROUP BY id, pseudo, seclast, lastconnect, \'date d\\\\\'inscription\'\r\nORDER BY dateactivite ASC',19),(16,'Actions achetées depuis 9h','SELECT cacval.nom, ROUND( SUM( nbr * valeurunique ) , 2 ) AS Valeur, \'€\' AS \' \'\r\nFROM cacval, historique\r\nWHERE cacval.codesico = historique.codesico\r\nAND temps > UNIX_TIMESTAMP( DATE_FORMAT( NOW( ) , \'%Y-%m-%d 09:00:00\' ) )\r\nGROUP BY cacval.nom\r\nORDER BY Valeur DESC\r\nLIMIT 20',24),(17,'Supprimer vieux ordres','DELETE FROM `ordre`\r\nWHERE (\r\n`etat` = \'0\' OR `tempslim` < UNIX_TIMESTAMP( )\r\n) AND `datecreation` < UNIX_TIMESTAMP( ) -604800',20),(18,'Top fournisseur','SELECT count(  *  )  AS cpt, SUBSTRING( EMAIL, INSTR( EMAIL,  \'@\'  )  +1  )  AS provider\r\nFROM compte\r\nGROUP  BY provider\r\nORDER  BY cpt DESC',33),(19,'Nombre d\'ordres éxécutés par jour','SELECT FROM_UNIXTIME( temps, \'%d %M %Y\' ) AS \"Date d\'éxécution\", count( * ) as \"Nombre d\'ordres\", CONCAT(SUM(nbr*valeurunique),\' €\')  Volume\r\nFROM `historique`\r\nWHERE temps>UNIX_TIMESTAMP()-604800\r\nGROUP BY \"Date d\'éxécution\"\r\nORDER BY \"Date d\'éxécution\" DESC',44),(20,'Niveau des joueurs','SELECT `texteniveau` AS Niveau, COUNT( * ) AS Nombre\r\nFROM `niveau` , `compte`\r\nWHERE compte.idniveau = niveau.idniveau\r\nGROUP BY Niveau\r\nORDER BY niveau.idniveau',43),(21,'Les actions à acheter','SELECT nom AS \'Nom action\', valeur AS \'Actuel\', COUNT( * ) AS \'Nombre de joueur\', ROUND( ABS( AVG( ansvaleur ) - valeur )/valeur*100 , 2 ) AS diff, MAX(idcompte), ROUND(SUM(( valeur - ansvaleur ) * quant),2)  as benef, SUM(quant) as tot\r\nFROM cacval, portef\r\nWHERE portef.codesico = cacval.codesico AND idcompte\r\nIN ( 36, 237, 1259, 1199, 2658, 1094, 579, 914, 340, 966 )\r\nGROUP BY \'Nom action\', \'Actuel\'\r\nORDER BY tot DESC',18),(23,'Pseudo des actions à acheter','SELECT idcompte, pseudonyme\r\nFROM compte\r\nWHERE idcompte\r\nIN ( 36, 237, 1259, 1199, 2658, 1094, 579, 914, 340, 966 )\r\nORDER BY idcompte',11),(24,'VAD ?','SELECT compte.pseudonyme, portef. *\r\nFROM `portef` , compte\r\nWHERE quant <0 AND portef.idcompte = compte.idcompte',19),(25,'Essais de mot de passes','SELECT idcompte,count(*) as nbressai FROM `tabforcing` WHERE 1 group by idcompte ORDER BY nbressai DESC',15),(26,'Skin des joueurs','SELECT nomskin, COUNT( * )\r\nFROM compte, skin\r\nWHERE compte.skin = skin.idskin\r\nGROUP BY nomskin',4),(27,'Skin choisis par joueurs','SELECT `nomskin` , COUNT( * ) FROM `skin` , `compte` WHERE compte.skin = skin.idskin GROUP BY nomskin',3),(28,'Messages joueurs','SELECT c2.pseudonyme MessFrom, c1.pseudonyme MessTo, FROM_UNIXTIME( datemess ) , titre, corps\r\nFROM `messages` m, compte c1, compte c2\r\nWHERE idenvoyeur !=1\r\nAND c1.idcompte = m.idcompte\r\nAND c2.idcompte = m.idenvoyeur\r\nORDER BY `m`.`datemess` DESC \r\nLIMIT 15',893),(29,'Profits et Pertes des Joueurs','SELECT FROM_UNIXTIME( temps, \'%d %M %Y\' ) AS \"Date d\'éxécution\", SUM(IF(profit>0,profit,0)) as Profits,SUM(IF(profit<0,profit,0)) as Pertes\r\nFROM `historique`\r\nWHERE temps>UNIX_TIMESTAMP()-604800\r\nGROUP BY \"Date d\'éxécution\"\r\nORDER BY \"Date d\'éxécution\" DESC',311),(30,'Commentaire Aide','SELECT FROM_UNIXTIME( `datecomment` ) , pseudonyme, `textecomment` \r\nFROM `tabaidecomment` tc, compte c\r\nWHERE tc.idcompte = c.idcompte\r\nORDER BY `datecomment` DESC \r\nLIMIT 10',509),(31,'Commentaire faq','SELECT FROM_UNIXTIME( `datecomment` ) , pseudonyme, `textecomment` \r\nFROM `tabfaqcomment` tc, compte c\r\nWHERE tc.idcompte = c.idcompte\r\nORDER BY `datecomment` DESC \r\nLIMIT 10',511),(32,'Mess forum','SELECT pseudonyme, contenu\r\nFROM `compte` , `f_message` fm, `f_corps` fc\r\nWHERE fm.idmessage = fc.idmessage\r\nAND compte.idcompte = fm.idcompte\r\nORDER BY fm.idmessage DESC \r\nLIMIT 0 , 30',519),(33,'Joueurs vers Pro-at ( ip unique 24h)','SELECT FROM_UNIXTIME( tmps, \'%d %M %Y\' ) AS \"Date clic\",url, count( * ) as \"Nombre clics\"\r\nFROM (SELECT * FROM `statout` GROUP BY FROM_UNIXTIME( tmps, \'%d %M %Y\' ),ip) as stat\r\nGROUP BY \"Date clic\",url\r\nORDER BY tmps DESC',1071),(34,'Joueurs vers domaine ( ip unique 24h)','SELECT FROM_UNIXTIME( tmps, \'%d %M %Y\' ) AS \"Date clic\",SUBSTRING(url, 1,INSTR( url,  \'.eu\'  )  +3 ) as lurl, count( * ) as \"Nombre clics\"\r\nFROM (SELECT * FROM `statout` GROUP BY FROM_UNIXTIME( tmps, \'%d %M %Y\' ),ip) as stat\r\nGROUP BY \"Date clic\",lurl\r\nORDER BY tmps DESC',2017),(35,'Erreur reception mail','SELECT (SELECT count(  *  )  AS provider\r\nFROM compte cp\r\nWHERE cp.dateactivite=\'0\' and SUBSTRING( cp.EMAIL, INSTR( cp.EMAIL,  \'@\'  )  +1  ) = SUBSTRING( cpt.EMAIL, INSTR( cpt.EMAIL,  \'@\'  )  +1  )\r\n)/count(  *  )  AS cpt, SUBSTRING( EMAIL, INSTR( EMAIL,  \'@\'  )  +1  )  AS provider,count(  *  ) as nbmail\r\nFROM compte cpt\r\nGROUP  BY provider\r\nORDER  BY nbmail DESC',37);
/*!40000 ALTER TABLE `reqlist` ENABLE KEYS */;
UNLOCK TABLES;

