INSERT INTO `reqlistpublic` VALUES (3,'10 derniers inscrits aux dernieres 24h','SELECT pseudonyme,FROM_UNIXTIME(dateinscr) AS \"Date d\'inscription\" FROM compte where dateinscr>UNIX_TIMESTAMP()-24*3600 ORDER BY dateinscr DESC LIMIT 0,10'),(4,'10 Actions achetées et vendues depuis 2h','SELECT cacval.nom as Nom,historique.sens  as Sens,SUM(historique.nbr) as \'Quantitée\', SUM(historique.nbr * cacval.valeur)  AS \"Valeur\" FROM cacval,historique WHERE cacval.codesico = historique.codesico \r\nAND historique.temps>UNIX_TIMESTAMP()-2*3600\r\nGROUP BY cacval.nom,historique.sens ORDER BY \"Valeur ( € ) \" DESC LIMIT 10'),(2,'Les 5 actions les plus achetées depuis 9h aujourd\'hui','SELECT cacval.nom as Nom,ROUND(SUM(nbr*valeurunique),2) as Valeur, \'€\' as \'-\'  FROM cacval,historique WHERE cacval.codesico = historique.codesico AND temps>UNIX_TIMESTAMP( DATE_FORMAT( NOW( ) , \'%Y-%m-%d 09:00:00\' ) ) GROUP BY cacval.nom ORDER BY Valeur DESC LIMIT 5'),(1,'Nombre d\'ordres éxécutés par jour','SELECT FROM_UNIXTIME( temps, \'%d %M %Y\' ) AS \"Date d\'éxécution\", count( * ) as \"Nombre d\'ordres\", CONCAT(SUM(nbr*valeurunique),\' €\')  Volume\r\nFROM `historique`\r\nWHERE temps>UNIX_TIMESTAMP()-604800\r\nGROUP BY \"Date d\'éxécution\"\r\nORDER BY \"Date d\'éxécution\" DESC'),(5,'Profits et Pertes cumulées par jour','SELECT FROM_UNIXTIME( temps, \'%d %M %Y\' ) AS \"Date d\'éxécution\", SUM(IF(profit>0,profit,0)) as Profits,SUM(IF(profit<0,profit,0)) as Pertes\r\nFROM `historique`\r\nWHERE temps>UNIX_TIMESTAMP()-604800\r\nGROUP BY \"Date d\'éxécution\"\r\nORDER BY \"Date d\'éxécution\" DESC'),(6,'Meilleur vente aujourd\'hui','SELECT pseudonyme AS Pseudo, CONCAT(IF( profit >0, profit, 0 ),\' €\') AS Profits,nbr as Quantité, nom\r\nFROM `historique` , `compte` , `cacval`\r\nWHERE temps > UNIX_TIMESTAMP( DATE_FORMAT( NOW( ) , \'%Y-%m-%d 09:00:00\' ) )\r\nAND historique.idcompte = compte.idcompte and historique.codesico=cacval.codesico and sens=\'Vente\' GROUP BY historique.idcompte\r\nORDER BY profit DESC LIMIT 10');
/*!40000 ALTER TABLE `reqlistpublic` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `scores`
--

DROP TABLE IF EXISTS `scores`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `scores` (
  `idcompte` smallint(5) unsigned NOT NULL DEFAULT '0',
  `datescore` date NOT NULL DEFAULT '0000-00-00',
  `capitalscores` float(20,2) unsigned NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`idcompte`,`datescore`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

